import styles from './Background.module.css'
import { useAppWindowRender } from 'utils/zustand/useAppWindowRender'
import BgIcon from 'components/layout/background/components/BgIcon'
import myComputer from 'asset/images/myComputer.webp'
import trashIcon from 'asset/images/trash.webp'
import networkIcon from 'asset/images/network.webp'
import notePad from 'asset/images/notepad.webp'
import mapleImage from 'asset/images/maple.png'

export default function Background() {
  const { onClickWindowOpen } = useAppWindowRender()
  const bgIconArr = [
    {
      title: '내 정보',
      imgObj: { src: myComputer, alt: 'myComputer' },
      onDoubleClick: () => onClickWindowOpen('myInfoWindow'),
    },
    {
      title: '내 프로젝트',
      imgObj: { src: networkIcon, alt: 'networkIcon' },
      onDoubleClick: () => onClickWindowOpen('myProjectWindow'),
    },
    {
      title: 'Maple Hatch Pet',
      imgObj: { src: mapleImage, alt: 'Maple Hatch Pet' },
      onDoubleClick: () => onClickWindowOpen('mapleBrowserWindow'),
      hideOnMobile: true,
    },
    {
      title: '방명록',
      imgObj: { src: notePad, alt: 'networkIcon' },
      onDoubleClick: () => onClickWindowOpen('guestBookWindow'),
    },
    {
      title: '휴지통',
      imgObj: { src: trashIcon, alt: 'trashicon' },
      onDoubleClick: () => onClickWindowOpen('trashCanWindow'),
    },
  ]
  return (
    <div className={styles.boxContainer}>
      {bgIconArr.map(item => (
        <BgIcon
          key={item.title}
          title={item.title}
          imgObj={item.imgObj}
          onDoubleClick={item.onDoubleClick}
          hideOnMobile={item.hideOnMobile}
        />
      ))}
    </div>
  )
}
